class Solution {
    public String largestWordCount(String[] messages,String[] senders){
        Map<String,Integer> count=new HashMap<>();
        for(int i=0;i<messages.length;i++){
            int words=1;
            for(char ch:messages[i].toCharArray())if(ch==' ')words++;
            count.merge(senders[i],words,Integer::sum);
        }
        String answer="";
        int best=-1;
        for(Map.Entry<String,Integer> entry:count.entrySet())if(entry.getValue()>best||entry.getValue()==best&&entry.getKey().compareTo(answer)>0){
            best=entry.getValue();
            answer=entry.getKey();
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun largestWordCount(messages:Array<String>,senders:Array<String>):String{
        val count=HashMap<String,Int>();
        for(i in messages.indices)count[senders[i]]=(count[senders[i]]?:0)+messages[i].count{
            it==' '
        }+1;
        var answer="";
        var best=-1;
        for((sender,total) in count)if(total>best||total==best&&sender>answer){
            best=total;
            answer=sender
        };
        return answer
    }
}

