class Solution {
    public:string largestWordCount(vector<string>& messages,vector<string>& senders){
        unordered_map<string,int> count;
        for(int i=0;i<(int)messages.size();++i)count[senders[i]]+=1+std::count(messages[i].begin(),messages[i].end(),' ');
        string answer;
        int best=-1;
        for(auto& [sender,total]:count)if(total>best||total==best&&sender>answer){
            best=total;
            answer=sender;
        }
        return answer;
    }
};
